private void BindImageUrlPreview()
{
    string strImageUrl = (txtImageUrl.Text ?? string.Empty).Trim();
    if (!string.IsNullOrEmpty(strImageUrl))
    {
        imgImageUrl.ImageUrl = strImageUrl;
        ScriptManager.RegisterStartupScript(Page, Page.GetType(), "_showImageUrlTool",
            "document.getElementById('spanImageUrlTool').style.visibility='visible';", true);
    }
    else
    {
        imgImageUrl.ImageUrl = string.Empty;
    }
}

protected void imgDeleteImageUrl_Click(object sender, ImageClickEventArgs e)
{
    txtImageUrl.Text = string.Empty;
    imgImageUrl.ImageUrl = string.Empty;
}

